function protocolIndex(){return shell(`${pageHero('PROTOCOL','A private execution layer between chains.','Explore the roles, information boundaries, and implementation choices in the original Xythum design.',['DOCUMENTED VISION','RESEARCH-STAGE MATERIALS'])}<section class="section"><div class="container">${sectionHead('SYSTEM MAP','Eight roles. Different responsibilities.','The diagram shows how each component contributes to the proposed private execution layer.')}<div class="arch-grid">${architecture.map((x,i)=>`<article class="arch-card"><span class="num">0${i+1}</span><h3>${x.t}</h3><p>${x.p}</p><p><strong>${x.io}</strong></p><p>${x.a}</p></article>`).join('')}</div></div></section><section class="section"><div class="container">${sectionHead('PRIMITIVES','Mechanisms with distinct responsibilities.','Each primitive strengthens a different part of the system.')}<div class="topic-list">${Object.entries(topics).map(([slug,t])=>`<a class="topic-link" href="/protocol/${slug}"><small>${t.eyebrow}</small><h3>${t.title}</h3><p>${t.summary}</p></a>`).join('')}</div></div></section>`)}
